-- ATTR_GRP/ATTR/ANKEN/ATTR_IN_ANKENテーブルの新規作成(ATTR_GRP/ATTRはTBL_DEF定義自体は
-- 初期コミットから存在していたが、実テーブルはissue #84まで一度も作成されていなかった)
CREATE TABLE IF NOT EXISTS ATTR_GRP (
    ATTR_GRP_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    ATTR_GRP_NAME VARCHAR(256),
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ATTR (
    ATTR_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    ATTR_NAME VARCHAR(256),
    ATTR_VAL VARCHAR(256),
    NUM_MIN INT,
    NUM_MAX INT,
    ATTR_NOTE VARCHAR(256),
    ATTR_GRP_ID INT,
    ORD_IN_GRP INT,
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ANKEN (
    ANKEN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    ACCNT_ID INT,
    ANKEN_NAME VARCHAR(256),
    DESCRIPTION VARCHAR(8192),
    WORK_PLACE VARCHAR(256),
    TERM VARCHAR(256),
    AGE VARCHAR(256),
    BILLING_RATE VARCHAR(256),
    MIN_RATE_NUM INT,
    MAX_RATE_NUM INT,
    RECRUIT_NUM INT,
    STATUS INT,
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ATTR_IN_ANKEN (
    ATTR_IN_ANKEN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    ANKEN_ID INT,
    ATTR_ID INT,
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP
);

-- TBL_DEF: ANKEN/ATTR_IN_ANKENの新規テーブル定義









